// ---------------------------------------------------------------------------
// Limine requests. The bootloader scans the kernel image for these structures
// and fills in their `response` pointers before jumping to _start.
// ---------------------------------------------------------------------------

__attribute__((used, section(".limine_requests_start")))
static volatile uint64_t limine_requests_start[] = LIMINE_REQUESTS_START_MARKER;

__attribute__((used, section(".limine_requests")))
static volatile uint64_t limine_base_revision[] = LIMINE_BASE_REVISION(6);

__attribute__((used, section(".limine_requests")))
static volatile struct limine_framebuffer_request framebuffer_request = {
    .id = LIMINE_FRAMEBUFFER_REQUEST_ID, .revision = 0};

__attribute__((used, section(".limine_requests")))
static volatile struct limine_memmap_request memmap_request = {
    .id = LIMINE_MEMMAP_REQUEST_ID, .revision = 0};

__attribute__((used, section(".limine_requests")))
static volatile struct limine_hhdm_request hhdm_request = {
    .id = LIMINE_HHDM_REQUEST_ID, .revision = 0};

__attribute__((used, section(".limine_requests")))
static volatile struct limine_bootloader_info_request bootloader_info_request = {
    .id = LIMINE_BOOTLOADER_INFO_REQUEST_ID, .revision = 0};

__attribute__((used, section(".limine_requests")))
static volatile struct limine_firmware_type_request firmware_type_request = {
    .id = LIMINE_FIRMWARE_TYPE_REQUEST_ID, .revision = 0};

__attribute__((used, section(".limine_requests")))
static volatile struct limine_executable_address_request executable_address_request = {
    .id = LIMINE_EXECUTABLE_ADDRESS_REQUEST_ID, .revision = 0};

__attribute__((used, section(".limine_requests")))
static volatile struct limine_rsdp_request rsdp_request = {
    .id = LIMINE_RSDP_REQUEST_ID, .revision = 0};

__attribute__((used, section(".limine_requests")))
static volatile struct limine_date_at_boot_request date_request = {
    .id = LIMINE_DATE_AT_BOOT_REQUEST_ID, .revision = 0};

__attribute__((used, section(".limine_requests_end")))
static volatile uint64_t limine_requests_end[] = LIMINE_REQUESTS_END_MARKER;

// ---------------------------------------------------------------------------

static volatile bool breakpoint_hit;

static void breakpoint_handler(struct interrupt_frame *f) {
    (void)f;
    breakpoint_hit = true;
}

// The PIT (8254 timer), only used here to prove a device IRQ gets through.
#define PIT_CHANNEL0 0x40
#define PIT_COMMAND  0x43
#define PIT_HZ       1193182
#define PIT_TEST_HZ  100
#define PIT_TEST_TICKS 3

static volatile uint64_t pit_ticks;

static void pit_handler(struct interrupt_frame *f) {
    (void)f;
    pit_ticks++;
}

static void ok(const char *what) {
    kprintf(ANSI_GREEN "  [ ok ] " ANSI_RESET "%s\n", what);
}

static const char *memmap_type_name(uint64_t type) {
    switch (type) {
    case LIMINE_MEMMAP_USABLE: return "usable";
    case LIMINE_MEMMAP_RESERVED: return "reserved";
    case LIMINE_MEMMAP_ACPI_RECLAIMABLE: return "ACPI reclaimable";
    case LIMINE_MEMMAP_ACPI_NVS: return "ACPI NVS";
    case LIMINE_MEMMAP_BAD_MEMORY: return "bad memory";
    case LIMINE_MEMMAP_BOOTLOADER_RECLAIMABLE: return "bootloader reclaimable";
    case LIMINE_MEMMAP_EXECUTABLE_AND_MODULES: return "kernel and modules";
    case LIMINE_MEMMAP_FRAMEBUFFER: return "framebuffer";
    case LIMINE_MEMMAP_RESERVED_MAPPED: return "reserved (mapped)";
    default: return "unknown";
    }
}

// Run the PIT at 100 Hz on ISA IRQ 0 and wait for a few ticks to arrive
// through the I/O APIC. Interrupts must be on. A machine without a PIT (some
// newer laptops gate it off) gets a warning, not a panic.
static void irq_self_test(char *line, size_t size) {
    uint32_t gsi = irq_register(0, pit_handler);
    uint16_t divisor = PIT_HZ / PIT_TEST_HZ;
    outb(PIT_COMMAND, 0x34); // channel 0, low then high byte, mode 2 (rate generator)
    outb(PIT_CHANNEL0, divisor & 0xff);
    outb(PIT_CHANNEL0, divisor >> 8);

    // Time out by watching the PIT's own counter, which runs whether or not
    // its IRQ gets through: each time it reloads, 10 ms have passed. Give up
    // after 200 ms, or after many reads if the counter never moves (no PIT).
    uint16_t last = divisor;
    unsigned periods = 0;
    for (uint32_t reads = 0; pit_ticks < PIT_TEST_TICKS && periods < 20 && reads < 1000000; reads++) {
        outb(PIT_COMMAND, 0x00); // latch channel 0's count
        uint16_t count = inb(PIT_CHANNEL0);
        count |= (uint16_t)inb(PIT_CHANNEL0) << 8;
        if (count > last) periods++;
        last = count;
    }
    irq_unregister(0);
    uint64_t ticks = pit_ticks;

    if (ticks < PIT_TEST_TICKS) {
        kprintf(ANSI_YELLOW "  [warn] IRQ self-test: %lu of %d PIT ticks arrived (IRQ 0 -> GSI %u); no PIT?" ANSI_RESET
                "\n", ticks, PIT_TEST_TICKS, gsi);
        line[0] = '\0';
        return;
    }
    ksnprintf(line, size, "IRQ self-test passed (PIT IRQ 0 -> GSI %u through the I/O APIC, %lu ticks)", gsi, ticks);
}

static void warn_line(const char *what) {
    kprintf(ANSI_YELLOW "  [warn] %s" ANSI_RESET "\n", what);
}

// "1234.567 MHz"
static void format_mhz(char *buf, size_t size, uint64_t hz) {
    ksnprintf(buf, size, "%lu.%03lu MHz", hz / 1000000, hz / 1000 % 1000);
}

// Sleep 100 ms on the monotonic clock and count the ticks that came in
// meanwhile. Under a loaded emulator ticks can arrive late or merge, so
// anything from half to twice the expected count passes.
#define TIMER_TEST_MS 100

static void timer_self_test(char *line, size_t size) {
    uint64_t t0 = timer_ticks();
    uint64_t ns0 = clock_monotonic_ns();
    sleep_ms(TIMER_TEST_MS);
    uint64_t ns = clock_monotonic_ns() - ns0;
    uint64_t got = timer_ticks() - t0;
    uint64_t want = TIMER_TEST_MS * TIMER_HZ / 1000;
    if (ns < TIMER_TEST_MS * NS_PER_MS || got < want / 2 || got > want * 2) {
        ksnprintf(line, size, "timer self-test: sleep_ms(%d) took %lu us and %lu ticks, expected %lu", TIMER_TEST_MS,
                  ns / 1000, got, want);
        warn_line(line);
        line[0] = '\0';
        return;
    }
    ksnprintf(line, size, "timer self-test passed (sleep_ms(%d): %lu ticks at %d Hz)", TIMER_TEST_MS, got, TIMER_HZ);
}

static void print_date(int64_t unix_s) {
    struct date d;
    unix_to_date(unix_s, &d);
    kprintf("%04d-%02d-%02d %02d:%02d:%02d UTC", d.year, d.month, d.day, d.hour, d.minute, d.second);
}

static void print_cpu(void) {
    struct cpu_ident id;
    cpu_identify(&id);
    kprintf("  cpu:    %s (%s)\n", id.brand, id.vendor);
}

static void print_memory_map(void) {
    struct limine_memmap_response *mm = memmap_request.response;
    if (mm == NULL) panic("bootloader did not provide a memory map");

    uint64_t usable = 0;
    kprintf("\n  memory map (%lu entries):\n", mm->entry_count);
    for (uint64_t i = 0; i < mm->entry_count; i++) {
        struct limine_memmap_entry *e = mm->entries[i];
        if (e->type == LIMINE_MEMMAP_USABLE) usable += e->length;
        kprintf("%s    %016lx - %016lx  %8lu KiB  %s" ANSI_RESET "\n",
                e->type == LIMINE_MEMMAP_USABLE ? ANSI_GREEN : ANSI_GREY, e->base, e->base + e->length,
                e->length / 1024, memmap_type_name(e->type));
    }
    kprintf("  usable RAM: %lu MiB\n", usable / (1024 * 1024));
}

void kmain(void) {
    serial_init();
    // Printed before there is a screen: it goes to the serial port and the
    // kernel log, and the console shows it once it's up.
    kprintf("\n" ANSI_CYAN "  myos %s" ANSI_RESET "\n\n", MYOS_VERSION);

    if (!LIMINE_BASE_REVISION_SUPPORTED(limine_base_revision)) {
        kprintf("myos: bootloader does not support Limine base revision 6\n");
        halt_forever();
    }

    struct limine_framebuffer_response *fbr = framebuffer_request.response;
    struct limine_framebuffer *fb = (fbr && fbr->framebuffer_count) ? fbr->framebuffers[0] : NULL;
    bool have_screen = console_init(fb);

    const char *firmware = "unknown";
    if (firmware_type_request.response) {
        switch (firmware_type_request.response->firmware_type) {
        case LIMINE_FIRMWARE_TYPE_X86BIOS: firmware = "legacy BIOS"; break;
        case LIMINE_FIRMWARE_TYPE_EFI32: firmware = "UEFI (32-bit)"; break;
        case LIMINE_FIRMWARE_TYPE_EFI64: firmware = "UEFI (64-bit)"; break;
        }
    }
    if (bootloader_info_request.response)
        kprintf("  booted by %s %s via %s\n", bootloader_info_request.response->name,
                bootloader_info_request.response->version, firmware);
    if (have_screen)
        kprintf("  screen: %lux%lu, %u bpp\n", fb->width, fb->height, fb->bpp);
    else
        kprintf("  screen: no usable 32-bit framebuffer, serial only\n");
    if (hhdm_request.response)
        kprintf("  physical memory mapped at %p\n", (void *)hhdm_request.response->offset);
    print_cpu();
    kprintf("\n");

    gdt_init();
    ok("GDT and TSS loaded");

    idt_init();
    ok("IDT loaded (256 vectors)");

    // Prove the IDT works: trigger a breakpoint exception, let our handler
    // run, and check that execution resumes here afterwards.
    idt_set_handler(3, breakpoint_handler);
    __asm__ volatile("int3");
    idt_set_handler(3, NULL);
    if (!breakpoint_hit) panic("breakpoint self-test: handler did not run");
    ok("interrupt self-test passed (int3 handled and returned)");

    print_memory_map();
    kprintf("\n");

    if (hhdm_request.response == NULL) panic("bootloader did not provide the HHDM offset");
    pmm_init(memmap_request.response, hhdm_request.response->offset);
    struct pmm_stats mem = pmm_get_stats();
    char line[96];
    ksnprintf(line, sizeof line, "physical memory: %lu MiB total, %lu KiB used, %lu MiB free",
              mem.total_pages * PAGE_SIZE / (1024 * 1024),
              (mem.total_pages - mem.free_pages) * PAGE_SIZE / 1024,
              mem.free_pages * PAGE_SIZE / (1024 * 1024));
    ok(line);

    pmm_self_test(memmap_request.response);
    ok("page allocator self-test passed (pages allocated, written, checked and freed)");

    struct limine_executable_address_response *exe = executable_address_request.response;
    if (exe == NULL) panic("bootloader did not provide the kernel's physical address");
    vmm_init(memmap_request.response, exe->physical_base, exe->virtual_base);
    struct vmm_stats vm = vmm_get_stats();
    ksnprintf(line, sizeof line, "own page tables loaded (%lu 1G + %lu 2M + %lu 4K pages, %lu KiB of tables)",
              vm.pages_1g, vm.pages_2m, vm.pages_4k, vm.table_pages * PAGE_SIZE / 1024);
    ok(line);

    vmm_self_test();
    ok(vm.nx ? "paging self-test passed (map/unmap; .text, .rodata read-only; .data no-execute)"
             : "paging self-test passed (map/unmap; .text, .rodata read-only; CPU has no NX)");

    kheap_init();
    ksnprintf(line, sizeof line, "kernel heap at %p (grows on demand, up to %lu GiB)", (void *)KHEAP_BASE,
              KHEAP_MAX_SIZE >> 30);
    ok(line);

    kheap_self_test();
    struct kheap_stats heap = kheap_get_stats();
    ksnprintf(line, sizeof line, "heap self-test passed (%lu allocations and %lu frees, no leaks, %lu KiB mapped)",
              heap.total_allocs, heap.total_frees, heap.heap_bytes / 1024);
    ok(line);

    if (have_screen && !console_use_shadow_buffer())
        warn_line("console: no memory for a shadow buffer, drawing straight to the screen");

    acpi_init(rsdp_request.response ? rsdp_request.response->address : NULL);
    const struct acpi_info *acpi = acpi_get_info();
    ksnprintf(line, sizeof line, "ACPI %s (OEM %s): %lu tables via the %s", acpi->revision >= 2 ? "2.0+" : "1.0",
              acpi->oem_id, acpi->table_count, acpi->xsdt ? "XSDT" : "RSDT");
    ok(line);
    acpi_print_summary();

    apic_init();
    struct apic_info apic = apic_get_info();
    ksnprintf(line, sizeof line, "local APIC %u enabled (%s mode), I/O APIC pins masked (%u), 8259 PICs %s",
              apic.lapic_id, apic.x2apic ? "x2APIC" : "xAPIC", apic.ioapic_pins,
              acpi->pcat_compat ? "remapped and masked" : "absent");
    ok(line);

    sti();
    ok("interrupts enabled");

    irq_self_test(line, sizeof line);
    if (line[0]) ok(line);

    struct limine_date_at_boot_response *date = date_request.response;
    time_init(date != NULL, date ? date->timestamp : 0);
    struct time_info ti = time_get_info();
    char tsc[24], lapic_mhz[24];
    format_mhz(tsc, sizeof tsc, ti.tsc_hz);
    format_mhz(lapic_mhz, sizeof lapic_mhz, ti.lapic_timer_hz);
    ksnprintf(line, sizeof line, "timers calibrated against the %s: TSC %s%s, local APIC timer %s",
              ti.calibrated_with, tsc, ti.invariant_tsc ? " (invariant)" : "", lapic_mhz);
    ok(line);
    ksnprintf(line, sizeof line, "%d Hz tick from the local APIC timer; the monotonic clock reads the %s",
              TIMER_HZ, ti.clock_source);
    ok(line);

    timer_self_test(line, sizeof line);
    if (line[0]) ok(line);

    if (have_screen) {
        struct console_info con = console_get_info();
        uint64_t t0 = clock_monotonic_ns();
        console_redraw();
        uint64_t us = (clock_monotonic_ns() - t0) / 1000;
        ksnprintf(line, sizeof line, "console: %ux%u characters (%ux%u font, scale %u)%s, full redraw in %lu.%03lu ms",
                  con.cols, con.rows, con.font_w, con.font_h, con.scale, con.shadow ? ", shadow buffer" : "",
                  us / 1000, us % 1000);
        ok(line);
    }

    int64_t now;
    if (clock_realtime_ns(&now)) {
        kprintf("  wall clock: ");
        print_date(now / (int64_t)NS_PER_SEC);
        kprintf(" (from the bootloader)\n");
    } else {
        kprintf("  wall clock: unknown, the bootloader gave no date\n");
    }

    enum ps2_status ps2 = ps2_init(line, sizeof line);
    if (ps2 == PS2_READY) ok(line);
    else if (ps2 == PS2_FAILED) warn_line(line);
    else kprintf("  %s\n", line);
    bool keyboard = ps2 == PS2_READY;

#ifdef MYOS_CRASH_TEST
    // `make crash-test`: touch an unmapped address to exercise the
    // page-fault handler and the crash screen.
    kprintf("\n  crash test: writing to an unmapped address...\n");
    *(volatile uint64_t *)0xdeadbeef000 = 42;
#endif

    if (!(read_rflags() & RFLAGS_IF)) panic("interrupts were turned off during boot");

    kprintf("\n");
    if (keyboard) {
        kprintf(ANSI_YELLOW "  Kernel is up. Type help for a list of commands." ANSI_RESET "\n\n");
        shell_run();
    }
    kprintf(ANSI_YELLOW "  Kernel is up. No keyboard, so this CPU is going to sleep." ANSI_RESET "\n\n");
    // Sleep with interrupts on, so IRQs still get handled.
    for (;;) hlt();
}
